"proposal": {
  "capability": "deployment.set-probes",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "shop",
    "name": "orders",
    "uid": "uid-deployment-orders"
  },
  "params": {
    "container": "app",
    "readiness": {
      "timeoutSeconds": 10
    }
  },
  "expected_effect": "Allow the app more time to connect to the database before readiness probes time out.",
  "rationale": "The logs show the app is retrying database connections, but the readiness probe times out at 2s. Increasing the timeout to 10s gives the app more time to establish a connection before the probe fails.",
